    /// <summary>
    /// Computes time needed to receive a response from a Telegram server through a proxy. Can be called before authorization
    /// </summary>
    public Task<TdLib.TdApi.Objects.Seconds> PingProxyAsync(Proxy proxy = default)
    {

           using var activity =  StartCallActivity("PingProxyAsync", typeof(PingProxy).FullName ?? "PingProxyAsync");

           try
           {
             return client.PingProxyAsync(proxy);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
